-- Greentech · Migración de los datos del portal en Claude a Supabase
-- Ejecutar UNA vez en Supabase → SQL Editor, después de esquema.sql.
-- Se puede repetir: actualiza los registros sin duplicarlos.
-- Contenido: 304 productos con precio o ficha, 25 proveedores, 1 aliado y el catálogo técnico de inversores, paneles y baterías.

on conflict (coleccion, id) do update set datos = excluded.datos, actualizado = excluded.actualizado;
